begin;
create temporary table demo_actors on commit drop as select nullif(current_setting('atelier.demo_admin_id',true),'')::uuid admin_id,nullif(current_setting('atelier.demo_employee_id',true),'')::uuid employee_id,(now() at time zone 'Africa/Cairo')::date today;
do $$begin
 if not exists(select 1 from demo_actors a join public.profiles p on p.id=a.admin_id and p.active and p.role='admin' join public.profiles e on e.id=a.employee_id and e.active and e.role='employee') then raise exception 'verified_demo_actor_ids_required';end if;
 if not exists(select 1 from public.settings where id=true and not live_bookings_enabled and business_timezone='Africa/Cairo' and date_precision='day') then raise exception 'disabled_Cairo_prototype_required';end if;
 if exists(select 1 from public.dresses where id not in ('d0000000-0000-4000-8000-000000000001'::uuid,'d0000000-0000-4000-8000-000000000002'::uuid,'d0000000-0000-4000-8000-000000000003'::uuid,'d0000000-0000-4000-8000-000000000004'::uuid,'d0000000-0000-4000-8000-000000000005'::uuid,'d0000000-0000-4000-8000-000000000006'::uuid)) then raise exception 'non_demo_inventory_present_abort';end if;
 if exists(select 1 from public.customers where id not in ('e0000000-0000-4000-8000-000000000001'::uuid,'e0000000-0000-4000-8000-000000000002'::uuid,'e0000000-0000-4000-8000-000000000003'::uuid,'e0000000-0000-4000-8000-000000000004'::uuid,'e0000000-0000-4000-8000-000000000005'::uuid)) or exists(select 1 from public.bookings where id not in ('b0000000-0000-4000-8000-000000000001'::uuid,'b0000000-0000-4000-8000-000000000002'::uuid,'b0000000-0000-4000-8000-000000000003'::uuid,'b0000000-0000-4000-8000-000000000004'::uuid,'b0000000-0000-4000-8000-000000000005'::uuid)) then raise exception 'non_demo_records_present_abort';end if;
end $$;

